import org.junit.Test;
import static org.junit.Assert.*;
import java.security.NoSuchAlgorithmException;
import java.security.SecureRandom;
import java.util.Base64;

public class KeyPairTest {

    @Test
    public void generateKeyPair_GivenPublicKey_ReturnsSameKeyPair() throws NoSuchAlgorithmException {
        EdDSAPublicKey publicKey = KeyPairGenerator.generate();
        KeyPair keyPair = new KeyPair(publicKey);
        assertEquals(publicKey, keyPair.getPublicKey());
    }

    @Test
    public void generateKeyPair_GivenSecretSeed_ReturnsCorrectKeyPair() throws NoSuchAlgorithmException, GeneralSecurityException {
        char[] seed = "my_secret_seed".getBytes();
        KeyPair keyPair = KeyPair.fromSecretSeed(seed);
        assertEquals(2, keyPair.getPublicKey().getEncodedLength());
        assertEquals(32, keyPair.getSignerKey().getEncodedLength());
    }

    @Test
    public void generateKeyPair_GivenBip39Seed_ReturnsCorrectKeyPair() throws NoSuchAlgorithmException, GeneralSecurityException {
        byte[] bip39Seed = "my_bip39_seed".getBytes();
        int accountNumber = 123;
        KeyPair keyPair = KeyPair.fromBip39Seed(bip39Seed, accountNumber);
        assertEquals(2, keyPair.getPublicKey().getEncodedLength());
        assertEquals(32, keyPair.getSignerKey().getEncodedLength());
    }

    @Test
    public void generateKeyPair_GivenAccountId_ReturnsCorrectKeyPair() throws NoSuchAlgorithmException, GeneralSecurityException {
        String accountId = "my_account_id";
        KeyPair keyPair = KeyPair.fromAccountId(accountId);
        assertEquals(2, keyPair.getPublicKey().getEncodedLength());
        assertEquals(32, keyPair.getSignerKey().getEncodedLength());
    }

    @Test
    public void canSign_GivenCorrectSignature_ReturnsTrue() throws NoSuchAlgorithmException, GeneralSecurityException {
        KeyPair keyPair = new KeyPair(KeyPairGenerator.generate());
        byte[] data = "my_data".getBytes();
        byte[] signature = keyPair.sign(data);
        assertTrue(keyPair.verify(data, signature));
    }

    @Test
    public void canSign_GivenIncorrectSignature_ReturnsFalse() throws NoSuchAlgorithmException, GeneralSecurityException {
        KeyPair keyPair = new KeyPair(KeyPairGenerator.generate());
        byte[] data = "my_data".getBytes();
        byte[] signature = "incorrect_signature".getBytes();
        assertFalse(keyPair.verify(data, signature));
    }

    @Test
    public void sign_GivenCorrectDataAndSignature_ReturnsDecoratedSignature() throws NoSuchAlgorithmException {
        KeyPair keyPair = new KeyPair(KeyPairGenerator.generate());
        byte[] data = "my_data".getBytes();
        DecoratedSignature decoratedSignature = keyPair.sign(data);
        assertNotNull(decoratedSignature);
    }

    @Test
    public void sign_GivenIncorrectDataAndSignature_ReturnsNull() {
        KeyPair keyPair = new KeyPair(KeyPairGenerator.generate());
        byte[] data = "incorrect_data".getBytes();
        DecoratedSignature decoratedSignature = keyPair.sign(data);
        assertNull(decoratedSignature);
    }

    @Test
    public void verify_GivenCorrectDataAndSignature_ReturnsTrue() throws NoSuchAlgorithmException, GeneralSecurityException {
        KeyPair keyPair = new KeyPair(KeyPairGenerator.generate());
        byte[] data = "my_data".getBytes();
        byte[] signature = keyPair.sign(data);
        assertTrue(keyPair.verify(data, signature));
    }

    @Test
    public void verify_GivenIncorrectDataAndSignature_ReturnsFalse() throws NoSuchAlgorithmException, GeneralSecurityException {
        KeyPair keyPair = new KeyPair(KeyPairGenerator.generate());
        byte[] data = "my_data".getBytes();
        byte[] signature = "incorrect_signature".getBytes();
        assertFalse(keyPair.verify(data, signature));
    }

    @Test
    public void equals_GivenSameKeyPairs_ReturnsTrue() {
        KeyPair keyPair1 = new KeyPair(KeyPairGenerator.generate());
        KeyPair keyPair2 = new KeyPair(KeyPairGenerator.generate());
        assertTrue(keyPair1.equals(keyPair2));
    }

    @Test
    public void equals_GivenDifferentKeyPairs_ReturnsFalse() {
        KeyPair keyPair1 = new KeyPair(KeyPairGenerator.generate());
        KeyPair keyPair2 = new KeyPair(KeyPairGenerator.generate().duplicate());
        assertFalse(keyPair1.equals(keyPair2));
    }
}
